// PCN AI chat (thin version + Groq backup + checker). All rules, data and abilities live in the database (pcn_ai_prepare and the ai_* tables).
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const CORS = {
  "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Headers": "authorization, apikey, content-type, x-client-info",
      "Access-Control-Allow-Methods": "POST, OPTIONS",
      };
      const json = (o, s = 200) => new Response(JSON.stringify(o), { status: s, headers: { ...CORS, "Content-Type": "application/json" } });
      let DAILY_LIMIT = 10; // Quick mode questions a day
      let PRO_LIMIT = 5; // Pro mode questions a day
      let DEEP_LIMIT = 3; // Deep mode questions a day
      const PRO_FMT = "\n\nSTYLE: Pro mode. Write a focused answer in Markdown, about 150 to 220 words: one bold sentence with the main takeaway, then 3 to 5 bullet points (start each with '- ') giving the key numbers and reasons, then one line '**Outlook:**'. Use ONLY facts and numbers in the DATA and WEB NOTES. Never state one single cause as certain: say 'may', 'is consistent with' or 'reports say', because no one event is proven to move the whole market. Do not add explanations that are not in the DATA or WEB NOTES. Never write links or URLs. When a sentence uses an item from OUR NEWS, put its tag such as [N2] right after that sentence. Prefer OUR NEWS (it is the newest) over WEB NOTES. For a plain price or simple fact question, answer in 1 to 3 sentences with no headings.";
      const QUICK_FMT = "\n\nSTYLE: Quick mode. Answer briefly: 2 to 5 sentences or a short list, no headings.";
      const DEEP_FMT = "\n\nSTYLE: Deep mode. Write a full analysis in Markdown: '## TLDR' (2-3 sentences with the key numbers, then 3 numbered points: Primary reason, Secondary reasons, Near-term outlook), then '## Deep Dive' with '### 1.', '### 2.', '### 3.' sections each having **Overview:** and **What it means:**, then '## Conclusion' with a one-line **Market Outlook**. Use ONLY facts and numbers in the DATA and WEB NOTES. Never state one single cause as certain: say 'may', 'is consistent with' or 'reports say', because no one event is proven to move the whole market. Do not add explanations that are not in the DATA or WEB NOTES. Never write links or URLs. When a sentence uses an item from OUR NEWS, put its tag such as [N2] right after that sentence. Prefer OUR NEWS (it is the newest) over WEB NOTES. If something is not in the DATA, do not mention it. For a plain price or simple fact question, still answer in 1 to 3 sentences with no headings.";
      const GROQ_MODELS = (Deno.env.get("GROQ_MODELS") || "openai/gpt-oss-20b,openai/gpt-oss-120b").split(",").map((s) => s.trim()).filter(Boolean);
      const CHECK_ON = (Deno.env.get("AI_CHECK") || "off").toLowerCase() === "on"; // checker is off unless the secret AI_CHECK is set to on
      const GROQ_CTX = 22000; // Groq free tier takes smaller requests, so its copy of the data is trimmed

      const CHECK_SYSTEM =
        "You are a strict fact checker for a crypto price website. You get DATA, a QUESTION and an ANSWER. " +
          "If every number, name, exchange and claim in the ANSWER is supported by the DATA, reply with the ANSWER exactly as written. " +
            "Otherwise reply with a corrected ANSWER: fix wrong numbers using the DATA and remove any claim the DATA does not support. " +
              "Keep the same language, style, length and links. Reply with the final answer text only, with no notes, labels or explanation.";

              async function gemini(key, models, system, user, temp, maxTok, ms) {
                let status = 0;
                  for (const m of models) {
                      try {
                            const r = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${m}:generateContent`, {
                                    method: "POST",
                                            headers: { "Content-Type": "application/json", "x-goog-api-key": key },
                                                    body: JSON.stringify({
                                                              systemInstruction: { parts: [{ text: system }] },
                                                                        contents: [{ role: "user", parts: [{ text: user }] }],
                                                                                  generationConfig: { temperature: temp, maxOutputTokens: maxTok },
                                                                                          }),
                                                                                                  signal: ms ? AbortSignal.timeout(ms) : undefined,
                                                                                                        });
                                                                                                              if (r.status === 200) {
                                                                                                                      const j = await r.json();
                                                                                                                              const text = (j?.candidates?.[0]?.content?.parts || []).map((p) => p.text || "").join("").trim();
                                                                                                                                      if (text) return { text, status: 200 };
                                                                                                                                            } else status = r.status;
                                                                                                                                                } catch (_) {}
                                                                                                                                                  }
                                                                                                                                                    return { text: "", status };
                                                                                                                                                    }

                                                                                                                                                    // Live web search (Deep mode only). Runs on gemini-2.5-flash because Gemini 3 models have no free Google Search.
                                                                                                                                                    let SEARCH_MODEL = Deno.env.get("SEARCH_MODEL") || "gemini-2.5-flash";
                                                                                                                                                    let SEARCH_DAYS = 3;
                                                                                                                                                    const JUNK = /(^|\.)(youtube\.com|youtu\.be|facebook\.com|instagram\.com|tiktok\.com|x\.com|twitter\.com|pinterest\.com|quora\.com)$/i;
                                                                                                                                                    function okSource(u, t) { try { const h = new URL(u).hostname; if (JUNK.test(h)) return false; } catch (_) {} return !JUNK.test(String(t || "").trim().replace(/^www\./, "")); }

                                                                                                                                                    async function webSearch(key, q) {
                                                                                                                                                      try {
                                                                                                                                                          const r = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${SEARCH_MODEL}:generateContent`, {
                                                                                                                                                                method: "POST",
                                                                                                                                                                      headers: { "Content-Type": "application/json", "x-goog-api-key": key },
                                                                                                                                                                            body: JSON.stringify({
                                                                                                                                                                                    contents: [{ role: "user", parts: [{ text: "Today is " + new Date().toISOString().slice(0, 10) + ". Search the web for the latest, reliable information about this crypto question. Use ONLY news published in the last " + SEARCH_DAYS + " days; ignore older stories. Reply with 5 to 8 short factual bullet notes, each starting with its publication date. No prices unless a source states them, and do not add any fact that is not in a source. Question: " + q }] }],
                                                                                                                                                                                            tools: [{ google_search: {} }],
                                                                                                                                                                                                    generationConfig: { temperature: 0.2, maxOutputTokens: 900 },
                                                                                                                                                                                                          }),
                                                                                                                                                                                                                signal: AbortSignal.timeout(20000),
                                                                                                                                                                                                                    });
                                                                                                                                                                                                                        if (r.status !== 200) return { text: "", sources: [], status: r.status };
                                                                                                                                                                                                                            const j = await r.json();
                                                                                                                                                                                                                                const c = j?.candidates?.[0];
                                                                                                                                                                                                                                    const text = (c?.content?.parts || []).map((p) => p.text || "").join("").trim();
                                                                                                                                                                                                                                        const seen = new Set();
                                                                                                                                                                                                                                            const sources = [];
                                                                                                                                                                                                                                                for (const g of c?.groundingMetadata?.groundingChunks || []) {
                                                                                                                                                                                                                                                      const w = g?.web;
                                                                                                                                                                                                                                                            if (w?.uri && okSource(w.uri, w.title) && !seen.has(w.uri) && sources.length < 5) { seen.add(w.uri); sources.push({ title: String(w.title || "source").slice(0, 100), uri: w.uri }); }
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                    return { text, sources, status: 200 };
                                                                                                                                                                                                                                                                      } catch (_) { return { text: "", sources: [], status: 0 }; }
                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                      // Backup search on Tavily (1,000 free searches a month). Used when Google's search gives nothing.
                                                                                                                                                                                                                                                                      async function tavilySearch(key, q) {
                                                                                                                                                                                                                                                                        try {
                                                                                                                                                                                                                                                                            const r = await fetch("https://api.tavily.com/search", {
                                                                                                                                                                                                                                                                                  method: "POST",
                                                                                                                                                                                                                                                                                        headers: { "Content-Type": "application/json", Authorization: "Bearer " + key },
                                                                                                                                                                                                                                                                                              body: JSON.stringify({ query: q + " crypto", topic: "news", days: SEARCH_DAYS + 1, search_depth: "basic", max_results: 8, include_answer: false, exclude_domains: ["youtube.com", "facebook.com", "instagram.com", "tiktok.com", "x.com", "twitter.com", "pinterest.com", "quora.com"] }),
                                                                                                                                                                                                                                                                                                    signal: AbortSignal.timeout(15000),
                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                            if (r.status !== 200) return { text: "", sources: [], status: r.status };
                                                                                                                                                                                                                                                                                                                const j = await r.json();
                                                                                                                                                                                                                                                                                                                    const rows = (j?.results || []).filter((x) => x?.url && x?.content);
                                                                                                                                                                                                                                                                                                                        const text = rows.map((x) => "- " + String(x.title || "").slice(0, 120) + ": " + String(x.content).replace(/\s+/g, " ").slice(0, 320)).join("\n");
                                                                                                                                                                                                                                                                                                                            const sources = rows.filter((x) => okSource(x.url, x.title)).slice(0, 5).map((x) => ({ title: String(x.title || x.url).slice(0, 100), uri: x.url }));
                                                                                                                                                                                                                                                                                                                                return { text, sources, status: 200 };
                                                                                                                                                                                                                                                                                                                                  } catch (_) { return { text: "", sources: [], status: 0 }; }
                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                  // Backup search on Groq (only used when Google's search gives nothing). Uses the model's built-in browser search tool.
                                                                                                                                                                                                                                                                                                                                  async function groqSearch(key, q) {
                                                                                                                                                                                                                                                                                                                                    try {
                                                                                                                                                                                                                                                                                                                                        const r = await fetch("https://api.groq.com/openai/v1/chat/completions", {
                                                                                                                                                                                                                                                                                                                                              method: "POST",
                                                                                                                                                                                                                                                                                                                                                    headers: { "Content-Type": "application/json", Authorization: "Bearer " + key },
                                                                                                                                                                                                                                                                                                                                                          body: JSON.stringify({
                                                                                                                                                                                                                                                                                                                                                                  model: "openai/gpt-oss-120b",
                                                                                                                                                                                                                                                                                                                                                                          temperature: 0.2,
                                                                                                                                                                                                                                                                                                                                                                                  max_tokens: 900,
                                                                                                                                                                                                                                                                                                                                                                                          reasoning_effort: "low",
                                                                                                                                                                                                                                                                                                                                                                                                  tools: [{ type: "browser_search" }],
                                                                                                                                                                                                                                                                                                                                                                                                          messages: [{ role: "user", content: "Today is " + new Date().toISOString().slice(0, 10) + ". Search the web for the latest, reliable information about this crypto question. Use ONLY news published in the last " + SEARCH_DAYS + " days; ignore older stories. Reply with 5 to 8 short factual bullet notes, each starting with its publication date. No prices unless a source states them, and do not add any fact that is not in a source. Question: " + q }],
                                                                                                                                                                                                                                                                                                                                                                                                                }),
                                                                                                                                                                                                                                                                                                                                                                                                                      signal: AbortSignal.timeout(25000),
                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                              if (r.status !== 200) return { text: "", sources: [], status: r.status };
                                                                                                                                                                                                                                                                                                                                                                                                                                  const j = await r.json();
                                                                                                                                                                                                                                                                                                                                                                                                                                      const text = String(j?.choices?.[0]?.message?.content || "").trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                          const seen = new Set();
                                                                                                                                                                                                                                                                                                                                                                                                                                              const sources = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                  const found = JSON.stringify(j?.choices?.[0]?.message?.executed_tools || []).match(/https?:\/\/[^\s"\\)]+/g) || [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                      for (const u of found) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (okSource(u, "") && !seen.has(u) && sources.length < 5) { seen.add(u); let h = u; try { h = new URL(u).hostname.replace(/^www\./, ""); } catch (_) {} sources.push({ title: h, uri: u }); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return { text, sources, status: 200 };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } catch (_) { return { text: "", sources: [], status: 0 }; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                      async function groq(key, system, user, temp, maxTok, ms) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let status = 0, err = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          for (const m of GROQ_MODELS) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const r = await fetch("https://api.groq.com/openai/v1/chat/completions", {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            method: "POST",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    headers: { "Content-Type": "application/json", Authorization: "Bearer " + key },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            body: JSON.stringify({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      model: m,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                temperature: temp,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          max_tokens: maxTok,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ...(m.startsWith("openai/gpt-oss") ? { reasoning_effort: "low" } : {}),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              messages: [{ role: "system", content: system }, { role: "user", content: user }],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              signal: ms ? AbortSignal.timeout(ms) : undefined,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (r.status === 200) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const j = await r.json();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const text = String(j?.choices?.[0]?.message?.content || "").trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (text) return { text, status: 200 };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          err += " | empty reply from " + m;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } else { status = r.status; err += " | " + m + " " + r.status + ": " + (await r.text()).slice(0, 110); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } catch (e) { err += " | fetch failed: " + String(e).slice(0, 80); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (status === 404 || status === 401 || status === 403) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const lr = await fetch("https://api.groq.com/openai/v1/models", { headers: { Authorization: "Bearer " + key } });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (lr.status === 200) { const lj = await lr.json(); err += " | YOUR KEY CAN USE: " + (lj?.data || []).map((x) => x.id).join(", ").slice(0, 600); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              else err += " | model list status " + lr.status;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } catch (_) {}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return { text: "", status, err };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Deno.serve(async (req) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (req.method === "OPTIONS") return new Response("ok", { headers: CORS });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (req.method !== "POST") return json({ error: "method" }, 405);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const url = Deno.env.get("SUPABASE_URL");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const anon = Deno.env.get("SUPABASE_ANON_KEY");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const srv = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const gkey = Deno.env.get("GEMINI_API_KEY");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const qkey = Deno.env.get("GROQ_API_KEY") || "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const tkey = Deno.env.get("TAVILY_API_KEY") || "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!url || !anon || !srv || !gkey) return json({ error: "setup" }, 500);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const auth = req.headers.get("Authorization") || "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const userClient = createClient(url, anon, { global: { headers: { Authorization: auth } } });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const { data: u } = await userClient.auth.getUser();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const user = u && u.user;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (!user) return json({ error: "signin" }, 401);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let body = {};
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      try { body = await req.json(); } catch (_) {}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const q = String(body.question || "").trim().slice(0, 400);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const chartCtx = typeof body.chart === "string" ? body.chart.trim().slice(0, 1800) : "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const mode = body.mode === "deep" ? "deep" : body.mode === "pro" ? "pro" : "quick";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const deep = mode === "deep";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (q.length < 2) return json({ error: "empty" }, 400);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const admin = createClient(url, srv);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Settings live in the ai_settings table, so they can be changed with SQL, with no redeploy
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const S = {};
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        try { const { data: sr } = await admin.from("ai_settings").select("key,value"); for (const r of sr || []) S[r.key] = String(r.value ?? ""); } catch (_) {}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const num = (k, d) => { const n = parseInt(S[k]); return n > 0 ? n : d; };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            DAILY_LIMIT = num("limit_quick", 10); PRO_LIMIT = num("limit_pro", 5); DEEP_LIMIT = num("limit_deep", 3);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (S.search_model && S.search_model.trim()) SEARCH_MODEL = S.search_model.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                SEARCH_DAYS = num("search_days", 3);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const searchModes = (S.search_modes || "deep").split(",").map((x) => x.trim());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const { data: prep, error: pe } = await admin.rpc("pcn_ai_prepare", { q, uid: user.id });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (pe || !prep) return json({ error: "data" }, 502);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (prep.greet) return json({ answer: prep.greet, left: null });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const { data: take } = mode === "deep"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ? await admin.rpc("pcn_chat_take_deep", { uid: user.id, lim: DEEP_LIMIT })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  : mode === "pro"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ? await admin.rpc("pcn_chat_take_pro", { uid: user.id, lim: PRO_LIMIT })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              : await admin.rpc("pcn_chat_take", { uid: user.id, lim: DAILY_LIMIT, total_lim: 300 });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (take === "limit") return json({ error: "limit", limit: mode === "deep" ? DEEP_LIMIT : mode === "pro" ? PRO_LIMIT : DAILY_LIMIT }, 429);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (take === "busy") return json({ error: "busy" }, 503);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const left = String(take || "").startsWith("ok:") ? Number(String(take).slice(3)) : null;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const refund = async () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const day = new Date().toISOString().slice(0, 10);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const tbl = mode === "deep" ? "pcn_chat_deep" : mode === "pro" ? "pcn_chat_pro" : "pcn_chat_usage";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const { data: r } = await admin.from(tbl).select("n").eq("user_id", user.id).eq("day", day).maybeSingle();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (r && r.n > 0) await admin.from(tbl).update({ n: r.n - 1 }).eq("user_id", user.id).eq("day", day);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } catch (_) {}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const ctx = String(prep.ctx || "");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let web = { text: "", sources: [], status: -1 };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const tried = {};
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (searchModes.includes(mode) && q.length >= 15) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // order comes from the ai_settings key search_order, e.g. "tavily,google,groq"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const order = (S.search_order || "tavily,google,groq").split(",").map((x) => x.trim().toLowerCase());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (const p of order) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (web.text) break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let r = null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (p === "tavily" && tkey) r = await tavilySearch(tkey, q);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    else if (p === "google") r = await webSearch(gkey, q);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          else if (p === "groq" && qkey) r = await groqSearch(qkey, q);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!r) continue;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      tried[p] = r.status;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (r.text) web = { ...r, via: p };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let ownNews = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      let newsBlock = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (mode !== "quick") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const { data: nr } = await admin.from("news").select("title,source,url,published_at,summary").order("published_at", { ascending: false }).limit(40);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const seenT = new Set();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              for (const r of nr || []) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const k = String(r.title || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").slice(0, 40);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!seenT.has(k) && /^https?:\/\//i.test(r.url || "") && ownNews.length < 10) { seenT.add(k); ownNews.push(r); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          newsBlock = "\nOUR NEWS (newest first, times are UTC; cite a used item by its tag such as [N2]):\n" + ownNews.map((r, i) => "[N" + (i + 1) + "] " + String(r.published_at).slice(0, 16).replace("T", " ") + " | " + r.source + " | " + r.title + (r.summary ? " | " + String(r.summary).slice(0, 160) : "")).join("\n") + "\n";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } catch (_) {}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const notes = newsBlock + (web.text ? "\nWEB NOTES (live web search; use for reasons and context only, prices and market numbers must come from DATA):\n" + web.text + "\n" : "");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const chartBlock = chartCtx ? "CHART DATA (live, in USD, read from the chart the user is looking at; use these exact numbers for any price, indicator or level; times are in the user's own timezone):\n" + chartCtx + "\n\n" : "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const userMsg = chartBlock + "DATA:\n" + ctx + "\n" + notes + "QUESTION: " + q;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 1. Writer: Gemini first, Groq if Gemini is out of quota or busy
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const TODAY = new Date().toISOString().slice(0, 10);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const DATE_RULE = "\n\nDATES: Today is " + TODAY + " (UTC). Compare every date you mention with today. If an event is dated after today, say it is upcoming or scheduled (for example: 'scheduled for Nov 22'), never as something that already happened. If it is dated before today, say it already happened. In a 'what matters today' answer put upcoming events in their own short line starting with 'Upcoming:' and keep the main bullets for what happened in the last few days. Never state a date you cannot find in the data or sources.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const sys = String(prep.system || "") + DATE_RULE + (S["style_" + mode] ? "\n\nSTYLE: " + S["style_" + mode] : (mode === "deep" ? DEEP_FMT : mode === "pro" ? PRO_FMT : QUICK_FMT));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let w = await gemini(gkey, prep.models || [], sys, userMsg, 0.4, 4096, 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  let by = "gemini";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!w.text && qkey) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        w = await groq(qkey, sys, chartBlock + "DATA:\n" + ctx.slice(0, GROQ_CTX) + "\n" + notes + "QUESTION: " + q, 0.4, mode === "quick" ? 2048 : 3500, 25000);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            by = "groq";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!w.text) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    await refund();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const busy = w.status === 429 || w.status === 503 || w.status === 413;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return json({ error: busy ? "busy" : "ai" }, busy ? 503 : 502);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // 2. Checker: the other provider reads the DATA and the answer, and fixes anything unsupported
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  let answer = w.text;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let checked = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      let why = CHECK_ON ? "" : "checker off";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!CHECK_ON) throw new Error("skip");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const chkUser = "DATA:\n" + ctx.slice(0, by === "gemini" ? GROQ_CTX : 60000) + "\n\nQUESTION: " + q + "\n\nANSWER:\n" + answer;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const c = by === "gemini"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ? (qkey ? await groq(qkey, CHECK_SYSTEM, chkUser, 0, 2048, 9000) : { text: "" })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                : await gemini(gkey, (prep.models || []).slice(0, 2), CHECK_SYSTEM, chkUser, 0, 2048, 9000);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const t = c.text.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        why = t ? "reply " + t.length + " chars vs answer " + answer.length : "no reply: status " + c.status + " " + (c.err || "");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // only accept a sensible reply: similar size, no notes about itself
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (t && t.length > answer.length * 0.5 && t.length < answer.length * 1.6 + 80 && !/^(answer|corrected|note|fact.?check)\b/i.test(t)) { answer = t; checked = true; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } catch (e) { if (CHECK_ON) why = "error " + String(e).slice(0, 120); }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const used = new Set();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      answer = answer.replace(/\s*\[N(\d+)\]/g, (_m, n) => { used.add(Number(n)); return ""; });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const srcList = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // everything that comes from our own website is listed first and marked "#pcn=" so the chat shows the PriceCheck NG logo
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            srcList.push({ title: "Live prices, market data and Fear & Greed", uri: "https://pricecheckng.com.ng/#pcn=" + encodeURIComponent("PriceCheck NG") });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              for (const n of [...used].sort((a, b) => a - b)) { const r = ownNews[n - 1]; if (r) srcList.push({ title: String(r.title).slice(0, 100), uri: r.url + "#pcn=" + encodeURIComponent(String(r.source || "News").slice(0, 40)) }); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for (const x of web.sources || []) srcList.push(x);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (srcList.length) answer += "\n\nSources: " + srcList.map((x) => "[" + String(x.title).replace(/[\[\]]/g, "") + "](" + x.uri + ")").join(" · ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    console.log("PCN_AI " + JSON.stringify({ mode, search: web.via || "none", tried, own_news: ownNews.length, cited: used.size, writer: by, checked, groq_key: !!qkey, why }));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return json({ answer, left });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      